{"code":"import pandas as pd, numpy as np, statsmodels.api as sm
D=pd.read_csv('data/explore.csv'); cols=['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']; Xlab=pd.get_dummies(D.lab,drop_first=True,dtype=float)
for c in cols:
 S=D[['tensile_mpa',c]].join(Xlab).dropna(); X=sm.add_constant(S[[c]+list(Xlab.columns)]);m=sm.OLS(S.tensile_mpa,X).fit()
 print(c, round(m.params[c],4), round(m.pvalues[c],6),round(m.rsquared,4),len(S))"}
